import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { useNavigate } from "react-router-dom";
import TabBar from "../../components/common/TabBar";
import BookingTile from "../../components/common/BookingTile";
import api from "../../utils/api";
import errorImage from "../../images/errorLoading.png";

/* ============================================================
   Styled Components
============================================================ */
const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  padding: 40px 0;
  display: flex;
  flex-direction: column;
  gap: 60px;
`;

const Section = styled.div`
  width: 100%;
`;

const SectionTitle = styled.h2`
  font-family: "Inter", sans-serif;
  font-size: 36px;
  font-weight: 800;
  color: #27374d;
  margin-bottom: 25px;
`;

const TilesContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 25px;
`;

const EmptyText = styled.p`
  font-size: 15px;
  color: #555;
`;

const ErrorText = styled.p`
  font-size: 14px;
  color: red;
`;

/* ============================================================
   Types
============================================================ */
type BookingApi = {
  _id: string;
  business: {
    businessName: string;
    address?: string;
    city?: string;
    profileImageUrl?: string;
  };
  services: {
    name: string;
    durationMinutes: number;
    priceBHD: number;
  }[];
  startTime: string;
  status: "pending" | "confirmed" | "completed" | "cancelled";
  staffName?: string | null;
};

type BookingCard = {
  id: string;
  date: string;
  image: string;
  salonName: string;
  location: string;
  services: string[];
  status: "upcoming" | "past";
};

/* ============================================================
   Component
============================================================ */
const BookingsPage: React.FC = () => {
  const navigate = useNavigate();

  const [upcoming, setUpcoming] = useState<BookingCard[]>([]);
  const [past, setPast] = useState<BookingCard[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadBookings = async () => {
      try {
        setLoading(true);

        const res = await api.get<BookingApi[]>("/bookings/me");
        const data = res.data || [];

        const now = new Date();

        const upcomingTmp: BookingCard[] = [];
        const pastTmp: BookingCard[] = [];

        data.forEach((b) => {
          const start = new Date(b.startTime);
          const isFuture = start >= now;

          const formattedDate = start.toLocaleString(undefined, {
            weekday: "short",
            month: "short",
            day: "numeric",
            hour: "numeric",
            minute: "2-digit",
          });

          const common: BookingCard = {
            id: b._id,
            date: formattedDate,
            image: b.business?.profileImageUrl || errorImage,
            salonName: b.business?.businessName || "Unknown Salon",
            location: `${b.business?.city || ""}${
              b.business?.city && b.business?.address ? " · " : ""
            }${b.business?.address || ""}`,
            services: (b.services || []).map((s) => s.name),
            status: "upcoming", // default, change below
          };

          // 🔥 STATUS NORMALIZATION HERE
          if (b.status === "pending" || b.status === "confirmed") {
            common.status = "upcoming";
            upcomingTmp.push(common);
          } else {
            common.status = "past";
            pastTmp.push(common);
          }
        });

        setUpcoming(upcomingTmp);
        setPast(pastTmp);
      } catch (err: any) {
        console.error(err);
        setError(
          err?.response?.data?.message || "Failed to load bookings."
        );
      } finally {
        setLoading(false);
      }
    };

    loadBookings();
  }, []);

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        {/* UPCOMING */}
        <Section>
          <SectionTitle>Upcoming Bookings</SectionTitle>

          {loading && <EmptyText>Loading your bookings...</EmptyText>}
          {error && <ErrorText>{error}</ErrorText>}
          {!loading && !error && upcoming.length === 0 && (
            <EmptyText>No upcoming bookings found.</EmptyText>
          )}

          <TilesContainer>
            {upcoming.map((b) => (
              <BookingTile
                key={b.id}
                {...b}
                onCancel={() => alert("Cancel not implemented")}
                onViewReceipt={() => navigate(`/bookings/${b.id}`)}
                onReschedule={() => alert("Reschedule coming soon")}
              />
            ))}
          </TilesContainer>
        </Section>

        {/* PAST */}
        <Section>
          <SectionTitle>Past Bookings</SectionTitle>

          {!loading && !error && past.length === 0 && (
            <EmptyText>No past bookings yet.</EmptyText>
          )}

          <TilesContainer>
            {past.map((b) => (
              <BookingTile
                key={b.id}
                {...b}
                onLeaveRating={() => alert("Add rating coming soon")}
                onViewReceipt={() => navigate(`/bookings/${b.id}`)}
              />
            ))}
          </TilesContainer>
        </Section>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default BookingsPage;
